// ---- the mod's own types and the globals the lifted code refers to ------------
struct Mat4 { float m[4][4]; };
struct CamSnap
{
    Mat4  view, proj;
    float nearC, farC;
    int   w, h;
    bool  valid;
};
static CamSnap camCur, camPrev;
static CamSnap sceneCand;
static float   sceneCandViewInv[16] = { 0 };
static bool    sceneCandHave = false;
static Mat4    sceneView;
static float   sceneViewInv[16];
static bool    haveScene = false, haveSceneViewInv = false;
static float   sceneViewInvPrev[16];
static bool    haveSceneViewInvPrev = false;
static const float kCamCutUnits = 15.0f;
static unsigned camCmpSerial = 0;
static float    m4bCurViewInv[16];
static inline void CamMatSet(float* dst, const void* src) { memcpy(dst, src, 64); camCmpSerial++; }
static __forceinline void CamDiffMax(const float* a, const float* b, float* rotMax, float* posMax)
{
    const __m128 absMask = _mm_castsi128_ps(_mm_set1_epi32(0x7FFFFFFF));
    __m128 m = _mm_setzero_ps();
    m = _mm_max_ps(_mm_and_ps(_mm_sub_ps(_mm_loadu_ps(a + 0), _mm_loadu_ps(b + 0)), absMask), m);
    m = _mm_max_ps(_mm_and_ps(_mm_sub_ps(_mm_loadu_ps(a + 4), _mm_loadu_ps(b + 4)), absMask), m);
    m = _mm_max_ps(_mm_and_ps(_mm_sub_ps(_mm_loadu_ps(a + 8), _mm_loadu_ps(b + 8)), absMask), m);
    m = _mm_max_ps(m, _mm_movehl_ps(m, m));
    m = _mm_max_ps(m, _mm_shuffle_ps(m, m, 1));
    __m128 p = _mm_and_ps(_mm_sub_ps(_mm_loadu_ps(a + 12), _mm_loadu_ps(b + 12)), absMask);
    p = _mm_and_ps(p, _mm_castsi128_ps(_mm_set_epi32(0, -1, -1, -1)));   // element 15 is not compared
    p = _mm_max_ps(p, _mm_setzero_ps());                                  // a NaN lane becomes the 0 it started as
    p = _mm_max_ps(p, _mm_movehl_ps(p, p));
    p = _mm_max_ps(p, _mm_shuffle_ps(p, p, 1));
    *rotMax = _mm_cvtss_f32(m);
    *posMax = _mm_cvtss_f32(p);
}

static int     patchCalls = 0;
static CamSnap patchedWith;
static void PatchProjection(const CamSnap& cam) { patchCalls++; patchedWith = cam; }

struct SceneCandE { CamSnap s; float vinv[16]; LONG draws; float dist; unsigned char rank; };
static const int  kSceneCandMax = 12;
static SceneCandE sceneCands[kSceneCandMax];
static int        sceneCandN    = 0;                    // candidates this frame
static int        sceneCandLive = -1;                   // the live anchor; sceneCand is a copy of it
static unsigned camCandFor = 0xFFFFFFFFu;    // the serial the candidate lookup holds (see camCmpSerial)
static int      camCandIdx = -1;             // the candidate the current c12 matches, -1 none
// Not DEVSTAT and not to be fenced: this line is inside the [equiv_c227: table] region, and the offline proof reads this
// counter to learn whether a frame re-elected.
static LONG statSceneReelected = 0;                     // frames the busiest candidate was not the live one
static LONG statSceneCandEvict = 0;                     // candidates evicted for want of a slot


// NoteSceneC227 from gate 3 on: s and vinv are the candidate the gates passed.
static void Offer(CamSnap s, Mat4 vinv)
{
    // The same camera again? The scene's viewport uploads c227 about ten times a frame: one entry per camera, matched as the draw
    // gate matches a draw; a repeat with a smaller near refreshes the snapshot.
    s.valid = true;
    int idx = -1;
    for (int i = 0; i < sceneCandN; i++)
    {
        float dR = 0.0f, dP = 0.0f;
        CamDiffMax(&vinv.m[0][0], sceneCands[i].vinv, &dR, &dP);
        if (dR < 1e-4f && dP < 0.05f) { idx = i; break; }
    }
    if (idx >= 0)
    {
        if (s.nearC < sceneCands[idx].s.nearC)
        {
            sceneCands[idx].s = s;
            if (idx == sceneCandLive) { sceneCand = s; camCur = s; }
        }
        return;
    }

        // The rank: continuous with last frame's elected camera, or not. The bars are the cut detector's: within kCamCutUnits, and a
    // rotation element within 0.6 (about 37 degrees). With no previous camera, or after a cut, every candidate is rank 1 and near
    // decides. dist (units plus scaled rotation) decides between two continuous candidates.
    unsigned char rank = 1;
    float dist = 0.0f;
    if (haveSceneViewInvPrev)
    {
        float cR = 0.0f, cP = 0.0f;
        CamDiffMax(&vinv.m[0][0], sceneViewInvPrev, &cR, &cP);
        if (cR < 0.6f && cP < kCamCutUnits) rank = 0;
        dist = cP + 10.0f * cR;
    }
    if (sceneCandN >= kSceneCandMax)
    {
                // Full: the passes come before the scene, so the scene must still find a slot. Evict the non-live entry with the fewest draws,
        // rank 1 before any rank 0 (the continuous candidates are the ones the election is between).
        int victim = -1;
        for (int i = 0; i < sceneCandN; i++)
        {
            if (i == sceneCandLive) continue;
            const SceneCandE& c = sceneCands[i];
            if (victim < 0 || c.rank > sceneCands[victim].rank
                || (c.rank == sceneCands[victim].rank && c.draws < sceneCands[victim].draws)) victim = i;
        }
        if (victim < 0) return;
        if (telemetryOn) { statSceneCandEvict++; }
        idx = victim;
    }
    else idx = sceneCandN++;
    {
        SceneCandE& e = sceneCands[idx];
        e.s = s; memcpy(e.vinv, vinv.m, 64); e.draws = 0; e.dist = dist; e.rank = rank;
    }
    camCandFor = 0xFFFFFFFFu;                  // the draw gate's lookup must see the new entry

        // The live anchor: a better rank; within rank 0 the candidate nearest last frame's camera; within rank 1 the smaller near.
    if (sceneCandLive >= 0)
    {
        const SceneCandE& L = sceneCands[sceneCandLive];
        const bool better = rank < L.rank
                         || (rank == L.rank && (rank == 0 ? dist < L.dist : s.nearC < L.s.nearC));
        if (!better) return;
    }
    sceneCandLive = idx;
    sceneCand = s;
    memcpy(sceneCandViewInv, vinv.m, 64);
    sceneCandHave = true;

        // Make it current now, not at EndScene: this upload precedes the scene's own draws, and the draw hook tests each draw's c12
    // against sceneViewInv, gated on camCur.valid. EndScene still copies the same values.
    camCur           = s;
    CamMatSet(sceneViewInv, vinv.m);
    haveSceneViewInv = true;

        // The jitter write belongs here: the one place per frame where the scene viewport is known and its matrices have just been read
    // unjittered (`s` is captured before the write, so camCur stays jitter-free). One Halton pair, guarded by patchedThisFrame.
    PatchProjection(s);

}
// The draw gate's evidence, for one draw whose c12..c15 is m4bCurViewInv and
// whose camMatch against the live anchor is given.
static void CountDraw(bool camMatch)
{
                // Which candidate this draw's camera is, memoised on camCmpSerial.
                if (camMatch) { if (sceneCandLive >= 0) sceneCands[sceneCandLive].draws++; }
                else if (sceneCandN > 1)
                {
                    if (camCandFor != camCmpSerial)
                    {
                        camCandFor = camCmpSerial; camCandIdx = -1;
                        for (int i = 0; i < sceneCandN; i++)
                        {
                            if (i == sceneCandLive) continue;
                            float dR = 0.0f, dP = 0.0f;
                            CamDiffMax(m4bCurViewInv, sceneCands[i].vinv, &dR, &dP);
                            if (dR < 1e-4f && dP < 0.05f) { camCandIdx = i; break; }
                        }
                    }
                    if (camCandIdx >= 0) sceneCands[camCandIdx].draws++;
                }

}
// hkEndScene's election, run when sceneCandHave.
static void Elect()
{
            // The election: the candidate the most draws were made with wins over the one the upload rules picked live. Ties,
            // and a frame with no draws counted, keep the live one.
            int best = sceneCandLive;
            for (int i = 0; i < sceneCandN; i++)
                if (sceneCands[i].draws > sceneCands[best].draws) best = i;
            if (best != sceneCandLive)
            {
                                // The increment lives in this condition and the equivalence proof depends on it (statSceneReelected): the
                // statement stays whole in every build.
                if (telemetryOn && ++statSceneReelected <= 12)
                    LogHealth("  scene camera: the live anchor (near %.3f far %.0f, %ld draws) was not the camera"
                        " the frame was drawn with; elected near %.3f far %.0f at %.1f %.1f %.1f with %ld draws"
                        " (%d candidates this frame). Next frame ranks continuity from the elected one.",
                        sceneCands[sceneCandLive].s.nearC, sceneCands[sceneCandLive].s.farC, sceneCands[sceneCandLive].draws,
                        sceneCands[best].s.nearC, sceneCands[best].s.farC,
                        sceneCands[best].vinv[12], sceneCands[best].vinv[13], sceneCands[best].vinv[14],
                        sceneCands[best].draws, sceneCandN);
                sceneCandLive = best;
                sceneCand = sceneCands[best].s;
                memcpy(sceneCandViewInv, sceneCands[best].vinv, 64);
            }

}

// ---- cameras ------------------------------------------------------------------
struct Cam { const char* name; float x, y, z; float yawDeg; float nearC, farC; };
static void MakeVinv(const Cam& c, Mat4* v)
{
    const float r = c.yawDeg * 3.14159265f / 180.0f, cs = cosf(r), sn = sinf(r);
    memset(v, 0, sizeof(*v));
    v->m[0][0] = cs;  v->m[0][1] = sn;  v->m[1][0] = -sn; v->m[1][1] = cs; v->m[2][2] = 1.0f;
    v->m[3][0] = c.x; v->m[3][1] = c.y; v->m[3][2] = c.z; v->m[3][3] = 1.0f;
}
static void MakeSnap(const Cam& c, CamSnap* s, Mat4* vinv)
{
    MakeVinv(c, vinv);
    memset(s, 0, sizeof(*s));
    // view = the rigid inverse of vinv: transpose the rotation, negate the translation
    for (int i = 0; i < 3; i++) for (int j = 0; j < 3; j++) s->view.m[i][j] = vinv->m[j][i];
    for (int j = 0; j < 3; j++) s->view.m[3][j] = -(vinv->m[3][0] * vinv->m[0][j] + vinv->m[3][1] * vinv->m[1][j] + vinv->m[3][2] * vinv->m[2][j]);
    s->view.m[3][3] = 1.0f;
    const float a = 1.0f / tanf(0.3927f), b = a * 16.0f / 9.0f;
    s->proj.m[0][0] = a; s->proj.m[1][1] = b;
    s->proj.m[2][2] = c.farC / (c.nearC - c.farC); s->proj.m[2][3] = -1.0f;
    s->proj.m[3][2] = c.nearC * c.farC / (c.nearC - c.farC);
    s->nearC = c.nearC; s->farC = c.farC; s->w = 3840; s->h = 2160; s->valid = false;
}
static void Upload(const Cam& c) { CamSnap s; Mat4 v; MakeSnap(c, &s, &v); Offer(s, v); }
// A draw with this camera's c12..c15: camMatch exactly as the gate computes it.
static void Draw(const Cam& c, int n)
{
    Mat4 v; MakeVinv(c, &v);
    CamMatSet(m4bCurViewInv, v.m);
    bool camMatch = false;
    if (haveSceneViewInv && camCur.valid)
    {
        float dR = 0.0f, dP = 0.0f;
        CamDiffMax(m4bCurViewInv, sceneViewInv, &dR, &dP);
        camMatch = (dR < 1e-4f && dP < 0.05f);
    }
    for (int i = 0; i < n; i++) CountDraw(camMatch);
}
static const Cam* gPool[64]; static int gPoolN = 0;
static void Know(const Cam& c) { if (gPoolN < 64) gPool[gPoolN++] = &c; }
// By pose, not position alone: the water reflection stands where the world
// camera stands, facing the other way.
static const Cam* Which(const float* vinv)
{
    for (int i = 0; i < gPoolN; i++)
    {
        Mat4 v; MakeVinv(*gPool[i], &v);
        if (v.m[3][0] == vinv[12] && v.m[3][1] == vinv[13] && v.m[3][2] == vinv[14]
            && fabsf(v.m[0][0] - vinv[0]) < 1e-5f && fabsf(v.m[0][1] - vinv[1]) < 1e-5f) return gPool[i];
    }
    return nullptr;
}
static const char* Name(const Cam* c) { return c ? c->name : "(none)"; }

// hkEndScene's tail for the selector: election, publish source, roll, per-frame reset.
static long gReelectBefore = 0;
static const Cam* EndScene(bool* reelected)
{
    gReelectBefore = statSceneReelected;
    const Cam* elected = nullptr;
    if (sceneCandHave)
    {
        Elect();
        camCur           = sceneCand;
        sceneView        = sceneCand.view;
        CamMatSet(sceneViewInv, sceneCandViewInv);
        haveScene        = true;
        haveSceneViewInv = true;
        elected = Which(sceneViewInv);
        if (!camCur.valid) Err("the elected camera is not marked valid");
    }
    else camCur.valid = false;
    if (haveSceneViewInv) { CamMatSet(sceneViewInvPrev, sceneViewInv); haveSceneViewInvPrev = true; }
    camPrev = camCur;
    camCur.valid  = false;
    sceneCandHave = false;
    sceneCandN = 0; sceneCandLive = -1; camCandFor = 0xFFFFFFFFu;
    if (reelected) *reelected = statSceneReelected != gReelectBefore;
    return elected;
}
static const Cam* Live() { return sceneCandHave ? Which(sceneCandViewInv) : nullptr; }
static void Reset()
{
    camCur.valid = false; camPrev.valid = false;
    sceneCandHave = false;
    sceneCandN = 0; sceneCandLive = -1; camCandFor = 0xFFFFFFFFu;
    haveScene = false; haveSceneViewInv = false; haveSceneViewInvPrev = false;
}
static void Expect(const char* what, const Cam* got, const Cam& want)
{
    if (got != &want) Err("%s: elected %s, wanted %s", what, Name(got), want.name);
}

// The OLD rule, as a reference model: smallest near among survivors, no continuity.
struct OldRule { const Cam* cam; float nearC; void Offer(const Cam& c) { if (!cam || c.nearC < nearC) { cam = &c; nearC = c.nearC; } } };

int main()
{
    setvbuf(stdout, nullptr, _IONBF, 0);
    const Cam WORLD  = { "world",  100.0f, 200.0f, 10.0f, 30.0f, 0.05f, 4500.0f };
    const Cam WORLD2 = { "world+", 100.5f, 200.4f, 10.0f, 31.0f, 0.05f, 4500.0f };   // one frame of travel
    const Cam CUT    = { "world/cut", 900.0f, -300.0f, 25.0f, 200.0f, 0.05f, 4500.0f };
    const Cam CUT2   = { "world/cut+", 900.4f, -299.6f, 25.0f, 201.0f, 0.05f, 4500.0f };
    const Cam PHONE  = { "phone",  1562.0f, 200.0f, 10.0f, 0.0f, 0.010f, 700.0f };
    const Cam PHONEC = { "phone/cut", 2362.0f, -300.0f, 25.0f, 0.0f, 0.010f, 700.0f };
    const Cam WATER  = { "water",  100.0f, 200.0f, 10.0f, 210.0f, 0.05f, 25000.0f };   // the same place, flipped
    const Cam MENU   = { "menu",   100.0f, 200.0f, 10.0f, 60.0f, 250.0f, 10000.0f };
    Cam lights[16];
    for (int i = 0; i < 16; i++) { lights[i] = { "light", 120.0f + 7.0f * i, 230.0f - 5.0f * i, 14.0f, 90.0f * (i % 4), 0.02f, 30.0f }; Know(lights[i]); }
    Know(WORLD); Know(WORLD2); Know(CUT); Know(CUT2); Know(PHONE); Know(PHONEC); Know(WATER); Know(MENU);
    static const char* lname[16] = { "light0", "light1", "light2", "light3", "light4", "light5", "light6", "light7",
                                     "light8", "light9", "light10", "light11", "light12", "light13", "light14", "light15" };
    for (int i = 0; i < 16; i++) lights[i].name = lname[i];
    bool re = false; const Cam* got = nullptr;
    long decidedByRank = 0, decidedByElection = 0;

    // 1. Startup equals the old rule, over a randomised order of the survivors.
    {
        std::mt19937 rng(12345);
        const Cam* set[4] = { &WORLD, &PHONE, &MENU, &WATER };
        for (int trial = 0; trial < 200; trial++)
        {
            Reset();
            int order[4] = { 0, 1, 2, 3 };
            for (int i = 3; i > 0; i--) { int j = (int)(rng() % (i + 1)); int t = order[i]; order[i] = order[j]; order[j] = t; }
            const int n = 1 + (int)(rng() % 4);
            OldRule old = { nullptr, 0.0f };
            for (int i = 0; i < n; i++) { Upload(*set[order[i]]); old.Offer(*set[order[i]]); }
            const Cam* live = Live();
            if (live != old.cam) Err("startup trial %d: live %s, the old rule says %s", trial, Name(live), Name(old.cam));
            EndScene(nullptr);      // no draws: the election keeps the live one
        }
        printf("  1. startup: 200 randomised trials agree with the old rule\n");
    }

    // 2. The phone never becomes the anchor while the world was elected last frame.
    {
        Reset();
        Upload(WORLD); Draw(WORLD, 4000); got = EndScene(&re); Expect("2 warm-up", got, WORLD);
        // world first, phone late (the measured order)
        Upload(WORLD2); Draw(WORLD2, 4000); Upload(PHONE); Draw(PHONE, 6);
        if (Live() != &WORLD2) Err("2a: the phone took the live anchor from the world (near 0.010 beat continuity)");
        got = EndScene(&re); Expect("2a", got, WORLD2); if (re) Err("2a: the election had to correct the live anchor");
        // phone first, then the world (the adversarial order)
        Upload(PHONE); Draw(PHONE, 6); Upload(WORLD2); Draw(WORLD2, 4000);
        if (Live() != &WORLD2) Err("2b: the world did not outrank the phone that arrived first");
        got = EndScene(&re); Expect("2b", got, WORLD2); if (re) Err("2b: the election had to correct the live anchor");
        decidedByRank += 2;
        printf("  2. the phone never wins the live anchor against an elected world, either order\n");
    }

    // 3. A cut with the phone up costs one frame.
    {
        Upload(CUT); Draw(CUT, 4000); Upload(PHONEC); Draw(PHONEC, 6);
        const Cam* live = Live();
        got = EndScene(&re); Expect("3 the cut frame", got, CUT);
        if (live == &PHONEC && !re) Err("3: the phone was live and the election did not correct it");
        if (live == &PHONEC) decidedByElection++;
        Upload(CUT2); Draw(CUT2, 4000); Upload(PHONEC); Draw(PHONEC, 6);
        if (Live() != &CUT2) Err("3: the frame after the cut did not rank from the elected world");
        got = EndScene(&re); Expect("3 the frame after", got, CUT2); if (re) Err("3: a second correction after the cut");
        printf("  3. a cut with the phone up: %s, corrected within the frame, quiet the frame after\n",
               live == &PHONEC ? "the phone won the live rank" : "the world kept the live rank");
    }

    // 4. Night lights before the scene, steady and across a cut.
    {
        Reset(); Upload(WORLD); Draw(WORLD, 4000); EndScene(nullptr);
        for (int k = 0; k < 5; k++) { Upload(lights[k]); Draw(lights[k], 120); }
        Upload(WORLD2); Draw(WORLD2, 4000);
        if (Live() != &WORLD2) Err("4a: a light held the live anchor against the continuous world");
        got = EndScene(&re); Expect("4a steady", got, WORLD2); if (re) Err("4a: a correction was needed");
        // the cut: nothing is continuous, the smallest near (a light) wins live
        for (int k = 0; k < 5; k++) { Upload(lights[k]); Draw(lights[k], 120); }
        Upload(CUT); Draw(CUT, 4000);
        const Cam* live = Live();
        got = EndScene(&re); Expect("4b the cut frame", got, CUT);
        if (live != &CUT && !re) Err("4b: a light was live and the election did not correct it");
        if (live != &CUT) decidedByElection++;
        for (int k = 0; k < 5; k++) { Upload(lights[k]); Draw(lights[k], 120); }
        Upload(CUT2); Draw(CUT2, 4000);
        if (Live() != &CUT2) Err("4c: the frame after the cut did not rank from the elected world");
        got = EndScene(&re); Expect("4c the frame after", got, CUT2); if (re) Err("4c: a second correction");
        printf("  4. five lights before the scene: steady, across a cut (%s), and the frame after\n",
               live != &CUT ? "a light won the live rank" : "the world kept the live rank");
    }

    // 5. Fourteen candidates before the scene: eviction keeps a slot.
    {
        Reset(); Upload(WORLD); Draw(WORLD, 4000); EndScene(nullptr);
        const long evBefore = statSceneCandEvict;
        for (int k = 0; k < 14; k++) { Upload(lights[k]); Draw(lights[k], 50 + k); }
        Upload(WORLD2); Draw(WORLD2, 4000);
        got = EndScene(&re); Expect("5", got, WORLD2);
        if (statSceneCandEvict == evBefore) Err("5: fourteen candidates did not evict anything, so the table is not what the test assumed");
        printf("  5. fourteen lights before the scene: %ld evicted, the scene elected\n", statSceneCandEvict - evBefore);
    }

    // 6. The water reflection at bootstrap.
    {
        Reset();
        Upload(WATER); Draw(WATER, 300); Upload(WORLD); Draw(WORLD, 4000);
        const Cam* live = Live();
        got = EndScene(&re); Expect("6 bootstrap", got, WORLD);
        if (live == &WATER && !re) Err("6: the water was live and the election did not correct it");
        if (live == &WATER) decidedByElection++;
        Upload(WATER); Draw(WATER, 300); Upload(WORLD2); Draw(WORLD2, 4000);
        if (Live() != &WORLD2) Err("6: the frame after bootstrap did not rank from the elected world");
        got = EndScene(&re); Expect("6 after", got, WORLD2); if (re) Err("6: a second correction");
        printf("  6. water at bootstrap: %s, the world elected, quiet the frame after\n",
               live == &WATER ? "the water won the live rank" : "the world kept the live rank");
    }

    // 7. Dedupe, and the smaller-near refresh.
    {
        Reset();
        for (int k = 0; k < 10; k++) Upload(WORLD);
        if (sceneCandN != 1) Err("7: ten uploads of one camera made %d candidates", sceneCandN);
        Cam nearer = WORLD; nearer.nearC = 0.03f;
        Upload(nearer);
        if (sceneCandN != 1) Err("7: a repeat with a smaller near made a new candidate");
        if (sceneCand.nearC != 0.03f || camCur.nearC != 0.03f) Err("7: the smaller near did not refresh the live snapshot (%.3f / %.3f)", sceneCand.nearC, camCur.nearC);
        EndScene(nullptr);
        printf("  7. ten uploads are one candidate; a smaller near refreshes the snapshot\n");
    }

    // 8. A Reset returns to startup behaviour.
    {
        Reset(); Upload(WORLD); Draw(WORLD, 4000); EndScene(nullptr);
        Reset();
        Upload(WORLD); Upload(PHONE);
        if (Live() != &PHONE) Err("8: after a Reset the old rule should decide (no previous camera), and it says the phone");
        Draw(WORLD, 4000); got = EndScene(&re); Expect("8", got, WORLD);
        printf("  8. after a Reset the old rule decides the live anchor and the election corrects it\n");
    }

    // 9. No draws counted: the live anchor stays.
    {
        Reset(); Upload(WORLD); Draw(WORLD, 4000); EndScene(nullptr);
        Upload(WORLD2); Upload(PHONE);
        got = EndScene(&re); Expect("9", got, WORLD2); if (re) Err("9: a correction with no evidence");
        printf("  9. a frame with no draws keeps the live anchor\n");
    }

    // 11. The headlight: a light camera three metres ahead of the chase camera,
    //     pointing the same way, uploading before the scene, every frame. It is
    //     continuous with last frame's camera and its near is smaller; the
    //     nearest-to-last-frame rule must keep the world live without a correction.
    {
        Reset(); Upload(WORLD); Draw(WORLD, 4000); EndScene(nullptr);
        Cam w = WORLD;
        long corrected = 0;
        for (int f = 0; f < 50; f++)
        {
            w.x += 0.3f; w.y += 0.2f; w.yawDeg += 0.4f;
            Cam head = w; head.name = "headlight"; head.nearC = 0.02f; head.farC = 40.0f;
            const float r = w.yawDeg * 3.14159265f / 180.0f;
            head.x += 3.0f * cosf(r); head.y += 3.0f * sinf(r);
            gPoolN = 0; Know(w); Know(head);
            Upload(head); Draw(head, 150);
            Upload(w); Draw(w, 3000);
            if (Live() != Which(&w.x) && Live() != nullptr && Live()->x != w.x) Err("11 frame %d: the headlight held the live anchor", f);
            got = EndScene(&re); if (!got || got->x != w.x) Err("11 frame %d: elected %s", f, Name(got));
            if (re) corrected++;
        }
        if (corrected) Err("11: %ld corrections against a headlight that is merely nearer and continuous", corrected);
        printf("  11. a headlight camera three metres ahead, same heading, before the scene: the world stays live, %ld corrections\n", corrected);
    }

    // 10. Fuzz: realistic frames, the world always drawing the most.
    {
        std::mt19937 rng(777);
        Reset();
        Cam world = WORLD; Cam phone = PHONE; bool phoneUp = false;
        long frames = 0, cutFrames = 0, corrections = 0;
        const Cam* elected = nullptr;
        for (int f = 0; f < 4000; f++)
        {
            // move, sometimes cut
            const bool cut = (rng() % 97) == 0;
            if (cut) { world.x += 300.0f + (rng() % 500); world.y -= 200.0f; world.yawDeg += 90.0f; cutFrames++; }
            else { world.x += 0.3f; world.y += 0.2f; world.yawDeg += 0.4f; }
            phone.x = world.x + 1462.0f; phone.y = world.y; phone.z = world.z;
            if ((rng() % 40) == 0) phoneUp = !phoneUp;
            // lights near the world this frame: some within 15 units, some pointing its way
            Cam near_[6];
            for (int i = 0; i < 6; i++)
            {
                near_[i] = lights[i];
                near_[i].x = world.x + 2.0f + 5.0f * i; near_[i].y = world.y - 4.0f + 3.0f * i;
                near_[i].yawDeg = world.yawDeg + (i % 3 == 0 ? 0.0f : 90.0f * i);
            }
            gPoolN = 0; Know(world); Know(phone); for (int i = 0; i < 6; i++) Know(near_[i]); for (int i = 0; i < 16; i++) Know(lights[i]); Know(WATER); Know(MENU);
            // the passes, in a plausible order: some lights, maybe water, the scene, maybe the phone late
            const int nl = (int)(rng() % 9);
            for (int k = 0; k < nl; k++) { Upload(lights[k]); Draw(lights[k], 20 + (int)(rng() % 200)); }
            const int nn = (int)(rng() % 4);
            for (int k = 0; k < nn; k++) { Upload(near_[k]); Draw(near_[k], 50 + (int)(rng() % 300)); }
            if ((rng() % 3) == 0) { Upload(WATER); Draw(WATER, (int)(rng() % 600)); }
            const int wd = 1000 + (int)(rng() % 3000);
            for (int u = 0; u < 1 + (int)(rng() % 3); u++) Upload(world);
            Draw(world, wd);
            if (phoneUp) { Upload(phone); Draw(phone, 6); }
            elected = EndScene(&re);
            frames++; if (re) corrections++;
            if (!elected || elected->x != world.x || elected->y != world.y)
                Err("fuzz frame %d: elected %s, the world drew the most (%d)%s", f, Name(elected), wd, cut ? " (a cut frame)" : "");
            if (re && !cut && f > 0)
            {
                // a correction outside a cut frame means the live rule lost to an impostor in a steady frame
                Err("fuzz frame %d: a correction on a steady frame (phone %s, %d lights, %d near)", f, phoneUp ? "up" : "down", nl, nn);
            }
        }
        printf("  10. fuzz: %ld frames, %ld cuts, %ld corrections (on cut frames and the first frame after the Reset), the world elected every frame\n",
               frames, cutFrames, corrections);
        decidedByElection += corrections;
    }

    printf("\n  the continuity rank decided %ld staged frames; the election corrected %ld frames; %ld evictions; %d PatchProjection calls\n",
           decidedByRank, decidedByElection, statSceneCandEvict, patchCalls);
    printf("%s\n", gErr ? "FAILED" : "PASS");
    return gErr ? 1 : 0;
}
